const fs = require('fs');

const tokens = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
if (tokens.length >= 2) {
    const r = parseInt(tokens[0], 10);
    const c = parseInt(tokens[1], 10);
    let idx = 2;
    const matrix = [];
    for (let i = 0; i < r; i++) {
        matrix.push(tokens.slice(idx, idx + c).map(Number));
        idx += c;
    }
    // Solve problem with matrix
}

